package com.avizero.avidrive.domain;
import jakarta.persistence.*;
@Entity @Table(name="uploads") public class Upload { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="session_uuid", unique=true) public String sessionUuid; @Column(name="owner_id") public Long ownerId; @Column(name="file_name") public String fileName; @Column(name="relative_path") public String relativePath; @Column(name="target_folder_id") public Long targetFolderId; @Column(name="total_size") public Long totalSize; @Column(name="chunk_size") public Long chunkSize; @Column(name="conflict_mode") public String conflictMode; public String status; @Column(name="received_bytes") public Long receivedBytes=0L; @Column(name="expires_at") public String expiresAt; }
